-- Mount Hyjal: the stage spawns that the Mount Hyjal spawn data does not have, and the phase changes that go with them.
--  * The Shrine of Goldrinn stage: Takrik Ragehowl, Ian Duran, Rio Duran and Royce Duskwhisper stand in phase 195 while the
--    shrine is overrun and have a second copy at the Maw of Lycanthoth in phase 3501 once the faction quest is rewarded.
--  * Gates of Sothann: the scene Commander Jarod Shadowsong stands in phase 170 (he ends Twilight Riot and gives and ends
--    Slash and Burn); the Jarod of the spawn data becomes the after copy in phase 3502 for the Firelord quests.
--  * The Firelands invasion stages 426, 433, 431, 432 and 425: spawns of those stages that have no copy in the spawn data.
-- Creature guids 9253000 and up, gameobject guids 1061000 and up. Positions, phases and addons as in The Cataclysm
-- Preservation Project 4.3.4.

DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9253000 AND 9253284;
DELETE FROM `creature` WHERE `guid` BETWEEN 9253000 AND 9253284;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 1061000 AND 1061014;




-- Takrik, Ian, Rio and Royce of the spawn data stand in the stage phase (their after copies are the 3501 spawns above)
UPDATE `creature` c JOIN (
SELECT 8268796 AS `g`, 39432 AS `e`, 5297.53 AS `x`, -2209.84 AS `y` UNION ALL
SELECT 8268795, 39433, 5309.59, -2207.87 UNION ALL
SELECT 8268808, 39434, 5302.76, -2213.68 UNION ALL
SELECT 8268797, 39435, 5301.19, -2215.24
) m ON c.`guid` = m.`g` AND c.`id` = m.`e` AND ABS(c.`position_x` - m.`x`) < 0.01 AND ABS(c.`position_y` - m.`y`) < 0.01 SET c.`phaseId` = 195;

-- the Jarod of the spawn data is the after copy (the 170 spawn above is the scene copy)
UPDATE `creature` c JOIN (
SELECT 8271453 AS `g`, 40772 AS `e`, 4100.15 AS `x`, -3989.43 AS `y`
) m ON c.`guid` = m.`g` AND c.`id` = m.`e` AND ABS(c.`position_x` - m.`x`) < 0.01 AND ABS(c.`position_y` - m.`y`) < 0.01 SET c.`phaseId` = 3502;

-- creature_template: Defender of Malorne was a level 90 placeholder (85 in both references)
UPDATE `creature_template` SET `minlevel` = 85, `maxlevel` = 85 WHERE `entry` = 52670 AND `minlevel` = 90 AND `maxlevel` = 90;
